vec3 palette( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263,0.416,0.557);

    return a + b*cos( 6.28318*(c*t+d) );
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
   // vec2 uv = fragCoord/iResolution.xy;


   // Output to screen
vec2 r =iResolution.xy;



    float l,z=iTime;
    vec3 c;
    vec2 uv,p=fragCoord.xy/r.xy;
    p.x*=r.x/r.y;
    uv=p;
    p*=13.5;
    p=fract(sin(p*1.));
    p-=.5;
    float d=length(abs(uv)-1.3);

    for(int i=0;i<3;i++){
        l=length(p);
        c[i]=sin(abs(10.1*d));
    }

    vec3 color=vec3(c);
    color=cos(abs(sin(z*1.))*mix(color,mix(palette(z)*1.4,vec3(.1333,.0431*z,.2745),abs(cos(z*100.))),1.));
    color*=(cos(palette(d*mod(z,1.))));

    fragColor=vec4(cos(color/l)*d*10.,1.);



    //fragColor = vec4(col,1.0);
}
